llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C08"],
      "claim": "In humans, only about 1.2% of a 6 mg synthetic lycopene dose dispersed in oil appeared in blood, showing that a large, highly lipophilic isoprenoid can have very low systemic availability after oral administration; this is structurally relevant to CoQ10's long decaprenyl chain.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "A controlled 13C-lycopene study reported 24.5±6% bioavailability for cis-lycopene, above the 20% threshold, indicating that some lipophilic isoprenoids can be absorbed to a meaningful extent.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Phytoene, a C40 isoprenoid hydrocarbon, was estimated to be 58% bioavailable in humans, suggesting long-chain isoprenoids are not inherently non-absorbable.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C15"],
      "claim": "Hyperforin, a polyprenylated phloroglucinol, showed high oral bioavailability from extract doses, providing a closer structural analogy to CoQ10's polyprenyl quinone and supporting potential absorption.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is CoQ10, an extremely lipophilic 863 Da quinone with a decaprenyl chain and no ionizable groups. Although high-transfer evidence from phytoene, hyperforin, and cis-lycopene suggests that some lipophilic isoprenoids can be absorbed, these are smaller molecules and mostly not absolute bioavailability measurements. The most structurally relevant all-trans lycopene data show very low systemic availability (0.17–2.6%), and the physicochemical prior predicts poor solubility and dissolution. On balance, F < 20% is better supported for this unformulated, highly lipophilic molecule.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability data for CoQ10 or a close quinone-containing analogue.",
    "Phytoene, hyperforin, and lycopene evidence is not absolute bioavailability and involves smaller molecules.",
    "The structurally relevant all-trans lycopene low-bioavailability records have very low assay-transfer scores, limiting their weight."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

